import{_ as r,c as o,o as t,a5 as a}from"./chunks/framework.DuCYAsAJ.js";const f=JSON.parse('{"title":"用户 API 处理器","description":"","frontmatter":{"title":"用户 API 处理器","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#2.2","branch":"main","level":1,"order":2.2},"headers":[],"relativePath":"posts/projects/zfeed/02-front-api-gateway/02-user-api-handlers.md","filePath":"posts/projects/zfeed/02-front-api-gateway/02-user-api-handlers.md","lastUpdated":1779632679000}'),i={name:"posts/projects/zfeed/02-front-api-gateway/02-user-api-handlers.md"};function l(c,e,n,p,s,g){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="用户-api-处理器" tabindex="-1">用户 API 处理器 <a class="header-anchor" href="#用户-api-处理器" aria-label="Permalink to &quot;用户 API 处理器&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/user/user.api" target="_blank" rel="noreferrer">app/front/doc/user/user.api</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/handler/content/editarticlehandler.go" target="_blank" rel="noreferrer">app/front/internal/handler/content/editarticlehandler.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/handler/content/editvideohandler.go" target="_blank" rel="noreferrer">app/front/internal/handler/content/editvideohandler.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/handler/search/searchcontentshandler.go" target="_blank" rel="noreferrer">app/front/internal/handler/search/searchcontentshandler.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/handler/search/searchusershandler.go" target="_blank" rel="noreferrer">app/front/internal/handler/search/searchusershandler.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/handler/user/queryfollowershandler.go" target="_blank" rel="noreferrer">app/front/internal/handler/user/queryfollowershandler.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/handler/user/updateprofilehandler.go" target="_blank" rel="noreferrer">app/front/internal/handler/user/updateprofilehandler.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/getmelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/getmelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/getmelogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/getmelogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/loginlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/loginlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/loginlogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/loginlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/profilecounts_helper.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/profilecounts_helper.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/queryfollowerslogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/queryfollowerslogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/queryuserprofilelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/queryuserprofilelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/queryuserprofilelogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/queryuserprofilelogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/registerlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/registerlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/registerlogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/registerlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/uploadavatarlogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/uploadavatarlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/client/contentservice/contentservice.go" target="_blank" rel="noreferrer">app/rpc/content/client/contentservice/contentservice.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/cleanup_follow_inbox_zset.lua" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/cleanup_follow_inbox_zset.lua</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/cleanupfollowinboxlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/cleanupfollowinboxlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/svc/delayed_cache_invalidator.go" target="_blank" rel="noreferrer">app/rpc/count/internal/svc/delayed_cache_invalidator.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/loginlogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/loginlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/mobile_test.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/mobile_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic_defaults_test.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic_defaults_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go</a></li></ul></details><p><code>front-api</code> 网关是所有用户相关操作的主要入口。它编排对 <code>user-rpc</code>、<code>count-rpc</code> 和 <code>interaction-rpc</code> 的请求，为资料管理、认证和社交图谱查询提供统一的 HTTP 接口。</p><h2 id="认证与生命周期" tabindex="-1">认证与生命周期 <a class="header-anchor" href="#认证与生命周期" aria-label="Permalink to &quot;认证与生命周期&quot;">​</a></h2><p>用户生命周期操作负责创建账号和建立会话。网关负责 HTTP 请求/响应转换，真正的核心处理则委托给 <code>user-rpc</code> 服务。</p><h3 id="注册与登录" tabindex="-1">注册与登录 <a class="header-anchor" href="#注册与登录" aria-label="Permalink to &quot;注册与登录&quot;">​</a></h3><p><code>Register</code> 和 <code>Login</code> 处理器会先校验输入（例如通过 <code>mobilex.IsValid</code> 校验手机号格式），再调用对应的 RPC 方法。</p><ul><li>注册：<code>user-rpc</code> 服务在 MySQL 中创建新的 <code>ZfeedUser</code> 记录，<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go#L95-L117" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go#95-117</a> 生成随机 16 字节盐值，<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go#L104-L111" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go#104-111</a> 并使用 <code>bcrypt</code> 对密码进行哈希。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go#L69-L72" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go#69-72</a></li><li>登录：根据存储的 <code>PasswordHash</code> 和 <code>PasswordSalt</code> 校验凭证。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/loginlogic.go#L55-L57" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/loginlogic.go#55-57</a> 成功后生成会话 token，并以可配置 TTL 持久化到 Redis。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go#L91-L95" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go#91-95</a></li></ul><h3 id="数据流-注册" tabindex="-1">数据流：注册 <a class="header-anchor" href="#数据流-注册" aria-label="Permalink to &quot;数据流：注册&quot;">​</a></h3><p>下图将注册流程从 HTTP handler 映射到持久化层。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/registerlogic.go#L32-L94" target="_blank" rel="noreferrer">app/front/internal/logic/user/registerlogic.go#32-94</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go#L38-L102" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go#38-102</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go#L95-L117" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go#95-117</a></p><h2 id="资料获取与聚合" tabindex="-1">资料获取与聚合 <a class="header-anchor" href="#资料获取与聚合" aria-label="Permalink to &quot;资料获取与聚合&quot;">​</a></h2><p>资料获取是一个高扇出操作。网关会并发获取基础信息、交互计数和关系状态。</p><h3 id="getme-与-queryuserprofile" tabindex="-1">GetMe 与 QueryUserProfile <a class="header-anchor" href="#getme-与-queryuserprofile" aria-label="Permalink to &quot;GetMe 与 QueryUserProfile&quot;">​</a></h3><p><code>GetMeLogic</code> 和 <code>QueryUserProfileLogic</code> 都使用 <code>sync.WaitGroup</code> 并发执行三类 RPC 调用：</p><ol><li>用户数据：从 <code>UserRpc.GetMe</code> 或 <code>UserRpc.GetUserProfile</code> 获取。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/getmelogic.go#L54-L54" target="_blank" rel="noreferrer">app/front/internal/logic/user/getmelogic.go#54</a></li><li>计数数据：从 <code>CountRpc.GetUserProfileCounts</code> 获取。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/profilecounts_helper.go#L21-L28" target="_blank" rel="noreferrer">app/front/internal/logic/user/profilecounts_helper.go#21-28</a></li><li>关注摘要：从 <code>FollowRpc.GetFollowSummary</code> 获取。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/profilecounts_helper.go#L30-L48" target="_blank" rel="noreferrer">app/front/internal/logic/user/profilecounts_helper.go#30-48</a></li></ol><h3 id="优雅降级" tabindex="-1">优雅降级 <a class="header-anchor" href="#优雅降级" aria-label="Permalink to &quot;优雅降级&quot;">​</a></h3><p>为了保障高可用，系统对非关键数据实现了降级策略：</p><ul><li>计数超时：计数请求默认超时时间为 200ms。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/profilecounts_helper.go#L12-L12" target="_blank" rel="noreferrer">app/front/internal/logic/user/profilecounts_helper.go#12</a> 如果失败或超时，逻辑会使用零值作为默认结果，而不是让整个请求失败。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/getmelogic.go#L75-L81" target="_blank" rel="noreferrer">app/front/internal/logic/user/getmelogic.go#75-81</a></li><li>关注数据源优先级：粉丝数和关注数优先使用 <code>interaction-rpc</code>（Follow Summary）提供的数据，因为它拥有最准确的实时社交图谱；如果不可用，再回退到 <code>count-rpc</code> 的值。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/profilecounts_helper.go#L50-L74" target="_blank" rel="noreferrer">app/front/internal/logic/user/profilecounts_helper.go#50-74</a></li></ul><h3 id="实体映射-资料聚合" tabindex="-1">实体映射：资料聚合 <a class="header-anchor" href="#实体映射-资料聚合" aria-label="Permalink to &quot;实体映射：资料聚合&quot;">​</a></h3><p>该图展示逻辑上的 <code>UserProfile</code> 如何由多个不同 RPC 服务组装而成。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/queryuserprofilelogic.go#L35-L117" target="_blank" rel="noreferrer">app/front/internal/logic/user/queryuserprofilelogic.go#35-117</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/profilecounts_helper.go#L50-L74" target="_blank" rel="noreferrer">app/front/internal/logic/user/profilecounts_helper.go#50-74</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/getmelogic.go#L34-L105" target="_blank" rel="noreferrer">app/front/internal/logic/user/getmelogic.go#34-105</a></p><h2 id="资料更新与媒体" tabindex="-1">资料更新与媒体 <a class="header-anchor" href="#资料更新与媒体" aria-label="Permalink to &quot;资料更新与媒体&quot;">​</a></h2><h3 id="updateprofile" tabindex="-1">UpdateProfile <a class="header-anchor" href="#updateprofile" aria-label="Permalink to &quot;UpdateProfile&quot;">​</a></h3><p>用户可以更新个人资料信息（昵称、简介、性别等）。<code>user-rpc</code> 中的 <code>UpdateProfile</code> 逻辑使用 <code>UserProfilePatch</code> 结构体，通过 GORM 执行局部更新。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go#L119-L169" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go#119-169</a> 它会检查字段是否存在，并动态构建 <code>updates</code> map，确保只修改 <code>zfeed_user</code> 表中请求实际提供的字段。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go#L124-L152" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go#124-152</a></p><h3 id="头像上传" tabindex="-1">头像上传 <a class="header-anchor" href="#头像上传" aria-label="Permalink to &quot;头像上传&quot;">​</a></h3><p><code>UploadAvatar</code> 处理器负责管理用户头像。虽然具体逻辑通常抽象到 OSS（Object Storage Service）中，但网关会处理 multipart 表单数据，并返回生成的 <code>ObjectKey</code> 和 <code>Url</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/user/user.api#L50-L55" target="_blank" rel="noreferrer">app/front/doc/user/user.api#50-55</a></p><h2 id="社交图谱-粉丝列表" tabindex="-1">社交图谱：粉丝列表 <a class="header-anchor" href="#社交图谱-粉丝列表" aria-label="Permalink to &quot;社交图谱：粉丝列表&quot;">​</a></h2><p><code>QueryFollowers</code> 端点提供用户粉丝的分页列表。</p><ul><li>请求：接收 <code>UserId</code>、<code>Cursor</code> 和 <code>PageSize</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/user/user.api#L92-L96" target="_blank" rel="noreferrer">app/front/doc/user/user.api#92-96</a></li><li>数据补全：逻辑会调用 <code>FollowRpc.ListFollowers</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/queryfollowerslogic_test.go#L32-L34" target="_blank" rel="noreferrer">app/front/internal/logic/user/queryfollowerslogic_test.go#32-34</a> 该 RPC 返回 <code>FollowerProfile</code> 对象，其中包含粉丝基础信息和 <code>IsFollowing</code> 标记，用于表示当前查看者是否也关注了该粉丝。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/queryfollowerslogic_test.go#L56-L58" target="_blank" rel="noreferrer">app/front/internal/logic/user/queryfollowerslogic_test.go#56-58</a></li></ul><table tabindex="0"><thead><tr><th>功能</th><th>RPC 服务</th><th>持久化</th><th>关键实现</th></tr></thead><tbody><tr><td>会话</td><td><code>user-rpc</code></td><td>Redis</td><td><code>SaveSession</code>、<code>GetSessionTTL</code></td></tr><tr><td>资料</td><td><code>user-rpc</code></td><td>MySQL</td><td><code>UpdateProfile</code>、<code>GetByID</code></td></tr><tr><td>计数</td><td><code>count-rpc</code></td><td>MySQL/Redis</td><td><code>GetUserProfileCounts</code></td></tr><tr><td>关注</td><td><code>interaction-rpc</code></td><td>MySQL</td><td><code>GetFollowSummary</code>、<code>ListFollowers</code></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/user/user.api#L111-L180" target="_blank" rel="noreferrer">app/front/doc/user/user.api#111-180</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go#L119-L169" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go#119-169</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/profilecounts_helper.go#L1-L79" target="_blank" rel="noreferrer">app/front/internal/logic/user/profilecounts_helper.go#1-79</a></p>',32)])])}const b=r(i,[["render",l]]);export{f as __pageData,b as default};
